{
  "candidate_id": "v79-r5-regression-2026-10-09-v77f-ad344a8b5f2d",
  "content_hash": "09302eeddc917d36b8ffcc53897bef83d802368a39df471ae4146e007f3fa47f",
  "claims": [
    {
      "claim": "Option A describes a short-term deposit.",
      "basis": "stem"
    },
    {
      "claim": "Option A says the deposit is readily convertible and subject to insignificant value risk.",
      "basis": "stem"
    },
    {
      "claim": "Option A matures within three months of acquisition because it matures in two months.",
      "basis": "arithmetic"
    },
    {
      "claim": "Options C and D exceed the excerpt’s three-month-or-less maturity benchmark: their maturities are five years and four months, respectively.",
      "basis": "arithmetic"
    },
    {
      "claim": "Option B does not state low risk or a short maturity and says no redemption date is stated.",
      "basis": "stem"
    },
    {
      "claim": "The explanation treats those omissions in B as establishing that B cannot qualify.",
      "basis": "unsupported"
    },
    {
      "claim": "Option A’s facts establish conversion into known amounts of cash, as required by the excerpt’s definition.",
      "basis": "unsupported"
    }
  ],
  "passed": false,
  "reasons": [
    "The excerpt requires convertibility into known amounts of cash; A states only that it is readily convertible, so the key is not fully established.",
    "B’s missing stated features do not establish that it fails the criteria; the excerpt does not categorically exclude shares."
  ],
  "evidence_ids": [
    "E1.1"
  ],
  "resolution_audit": {
    "key": "A",
    "key_fully_supported": false,
    "key_reason": "A meets the stated maturity, convertibility, and value-risk facts, but does not establish conversion into known amounts of cash as E1.1 requires.",
    "unexcluded_rival_conditions": [
      "B is not ruled out if it has maturity of three months or less from acquisition, is readily convertible into known amounts of cash, and carries insignificant value risk; the stem leaves those facts unstated."
    ],
    "distractors": [
      {
        "option": "B",
        "decisively_wrong": false,
        "basis": "source_silence",
        "reason": "E1.1 does not categorically exclude shares; no stated redemption date does not establish that B fails the maturity or other criteria."
      },
      {
        "option": "C",
        "decisively_wrong": true,
        "basis": "direct_contradiction",
        "reason": "Its five-year maturity exceeds E1.1’s three-month-or-less benchmark."
      },
      {
        "option": "D",
        "decisively_wrong": true,
        "basis": "direct_contradiction",
        "reason": "Its four-month maturity exceeds E1.1’s three-month-or-less benchmark."
      }
    ]
  }
}
